/** Menu surface: menus are dark in both themes */
export const EVENT_DETAIL_MENU_CLASS = "bg-[#252525] border-[#303030]";

/** A menu item on `EVENT_DETAIL_MENU_CLASS` */
export const EVENT_DETAIL_MENU_ITEM_CLASS =
