"use client";

import * as React from "react";
import { addDays, differenceInCalendarDays } from "date-fns";
import { Clock9 } from "lucide-react";

import { cn } from "@/lib/utils";
import { Switch } from "@/components/ui/switch";
import { useCalendarConfig } from "./calendar-provider";
import { EventDetailDateField } from "./event-detail-date-field";
import {
  EVENT_DETAIL_MUTED_CLASS,
  EVENT_DETAIL_ROW_HEIGHT_CLASS,
  EVENT_DETAIL_SECONDARY_CLASS,
  EVENT_DETAIL_TEXT_CLASS,
  EventDetailRow,
  EventDetailSection,
} from "./event-detail-parts";
import { EventDetailTimeField } from "./event-detail-time-field";
import { formatTime } from "@/lib/event-utils";
import {
  applyTimeToDate,
  endsOnLaterDay,
  formatDuration,
  getEndTimeOptions,
  getStartTimeOptions,
  hasTimeOfDay,
  matchEndTimes,
  matchStartTimes,
} from "@/lib/time-input";
import type {
  DetailedCalendarEvent,
  EventDetailSectionProps,
} from "./week-view-types";

/** Start hour given to an all-day event switched to timed when it has no times */
const DEFAULT_START_HOUR = 9;

/** End hour given to an all-day event switched to timed when it has no times */
const DEFAULT_END_HOUR = 10;

/** The clock and arrow of an all-day event, fainter than its times */
const ALL_DAY_ICON_CLASS = "text-[#EEEEEE] dark:text-[#303030]";

/** The duration of an all-day event, between its icons and its times */
const ALL_DAY_DURATION_CLASS = "text-[#D2D2D2] dark:text-[#373737]";

/**
 * The arrow between the times: Notion Calendar's is 13px wide and 10.5px
 * tall with 1.25px strokes, flatter than lucide's ArrowRight
 */
function TimeArrow({ className }: { className?: string }) {
  return (
    <svg
      aria-hidden
      width="14"
      height="12"
      viewBox="0 0 14 12"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.25}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn("shrink-0", className)}
    >
      <path d="M0.75 6h12.5M8.5 1.5 13.25 6 8.5 10.5" />
    </svg>
  );
}

/**
 * Start and end time with the duration, then the date, laid out on Notion
 * Calendar's columns: the times' text at 45px and 156px from the panel's
 * edge, the dates' under them. An all-day event shows its times muted and
 * inert (or none, when it has none) and its end date; so does a timed event
 * that ends on a later day. Without `onEventChange`, the fields only show
 * the event.
 */
export function EventDetailTime<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
>({ event, onEventChange }: EventDetailSectionProps<TEvent>) {
  const { hourCycle, locale } = useCalendarConfig();
  const sectionRef = React.useRef<HTMLDivElement>(null);
  const allDay = event.isAllDay ?? false;
  const showTimes = !allDay || hasTimeOfDay(event);
  const showEndDate = allDay || endsOnLaterDay(event.start, event.end);
  const readOnly = !onEventChange;

  /** "3 PM" / "3:30 PM", or "15:00" / "15:30" on a 24-hour clock */
  const formatTimeValue = React.useCallback(
    (date: Date) => formatTime(date, hourCycle, locale),
    [hourCycle, locale],
  );

  const startMs = event.start.getTime();
  const endMs = event.end.getTime();

  const getStartOptions = React.useCallback(
    () => getStartTimeOptions(new Date(startMs), formatTimeValue),
    [startMs, formatTimeValue],
  );

  const getEndOptions = React.useCallback(
    () =>
      getEndTimeOptions(new Date(startMs), new Date(endMs), formatTimeValue),
    [startMs, endMs, formatTimeValue],
  );

  const getStartMatches = React.useCallback(
    (typed: string) =>
      matchStartTimes(typed, new Date(startMs), hourCycle, formatTimeValue),
    [startMs, hourCycle, formatTimeValue],
  );

  const getEndMatches = React.useCallback(
    (typed: string) =>
      matchEndTimes(
        typed,
        new Date(startMs),
        new Date(endMs),
        hourCycle,
        formatTimeValue,
      ),
    [startMs, endMs, hourCycle, formatTimeValue],
  );

  /** A new start keeps the duration, as in Notion Calendar */
  const commitStart = (date: Date) => {
    onEventChange?.({
      ...event,
      start: date,
      end: new Date(date.getTime() + (endMs - startMs)),
    });
    return true;
  };

  const commitEnd = (date: Date) => {
    if (date.getTime() <= startMs) return false;
    onEventChange?.({ ...event, end: date });
    return true;
  };

  /** A new start date moves the whole event */
  const commitStartDate = (day: Date) => {
    const dayDiff = differenceInCalendarDays(day, event.start);
    onEventChange?.({
      ...event,
      start: addDays(event.start, dayDiff),
      end: addDays(event.end, dayDiff),
    });
    return true;
  };

  /** A new end date keeps the end time; it can't come before the start */
  const commitEndDate = (day: Date) => {
    const end = addDays(event.end, differenceInCalendarDays(day, event.end));
    const isBeforeStart = allDay
      ? differenceInCalendarDays(end, event.start) < 0
      : end.getTime() <= startMs;
    if (isBeforeStart) return false;
    onEventChange?.({ ...event, end });
    return true;
  };

  const iconClass = allDay ? ALL_DAY_ICON_CLASS : EVENT_DETAIL_MUTED_CLASS;

  return (
    <EventDetailSection ref={sectionRef} name="time">
      {showTimes && (
        <div className={cn("flex items-center", EVENT_DETAIL_ROW_HEIGHT_CLASS)}>
          {/* Clock ink at 18.5-34px, text at 45px */}
          <EventDetailTimeField
            value={event.start}
            getOptions={getStartOptions}
            getMatches={getStartMatches}
            onCommit={commitStart}
            formatValue={formatTimeValue}
            label="Start time"
            testId="event-start-time"
            panelRef={sectionRef}
            disabled={allDay}
            readOnly={readOnly}
            className="ml-[7px] w-[105px] shrink-0 gap-[10px] pl-[10px]"
            leading={
              <Clock9
                absoluteStrokeWidth
                strokeWidth={1.25}
                className={cn("size-[17px] shrink-0", iconClass)}
              />
            }
          />
          {/* Arrow ink at 129.5px, text at 156px; the box runs to 10px from the edge */}
          <EventDetailTimeField
            value={event.end}
            getOptions={getEndOptions}
            getMatches={getEndMatches}
            onCommit={commitEnd}
            formatValue={formatTimeValue}
            label="End time"
            testId="event-end-time"
            panelRef={sectionRef}
            disabled={allDay}
            readOnly={readOnly}
            fitText
            className="mr-[10px] ml-[5px] flex-1 gap-[12.5px] pl-[11.5px]"
            leading={<TimeArrow className={iconClass} />}
            trailing={
              <span
                className={cn(
                  "ml-1 shrink-0 whitespace-nowrap",
                  allDay
                    ? ALL_DAY_DURATION_CLASS
                    : EVENT_DETAIL_SECONDARY_CLASS,
                )}
              >
                {formatDuration(event.start, event.end)}
              </span>
            }
          />
        </div>
      )}

      <div className={cn("flex items-center", EVENT_DETAIL_ROW_HEIGHT_CLASS)}>
        {/* Text at 45px, under the start time */}
        <EventDetailDateField
          value={event.start}
          onCommit={commitStartDate}
          label="Start date"
          testId="event-start-date"
          panelRef={sectionRef}
          readOnly={readOnly}
          className="ml-[36px] w-[105px] shrink-0"
        />
        {/* The end date's text at 156px, under the end time */}
        {showEndDate && (
          <EventDetailDateField
            value={event.end}
            onCommit={commitEndDate}
            minDate={event.start}
            label="End date"
            testId="event-end-date"
            panelRef={sectionRef}
            readOnly={readOnly}
            className="mr-[10px] ml-[6px] flex-1"
          />
        )}
      </div>
    </EventDetailSection>
  );
}

/**
 * The all-day switch. The event keeps its times while it's all-day, and
 * switching off brings them back (9–10 AM for an event that has none).
 */
export function EventDetailAllDay<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
>({ event, onEventChange }: EventDetailSectionProps<TEvent>) {
  const allDay = event.isAllDay ?? false;

  const handleAllDayToggle = (checked: boolean) => {
    if (checked) {
      onEventChange?.({ ...event, isAllDay: true });
      return;
    }

    if (hasTimeOfDay(event)) {
      onEventChange?.({ ...event, isAllDay: false });
      return;
    }

    onEventChange?.({
      ...event,
      isAllDay: false,
      start: applyTimeToDate(event.start, DEFAULT_START_HOUR, 0),
      end: applyTimeToDate(event.end, DEFAULT_END_HOUR, 0),
    });
  };

  return (
    <EventDetailSection name="all-day">
      {/* Clicking the label or the row toggles too */}
      <EventDetailRow
        className="cursor-default"
        onClick={onEventChange ? () => handleAllDayToggle(!allDay) : undefined}
        leading={
          <Switch
            size="sm"
            checked={allDay}
            disabled={!onEventChange}
            onCheckedChange={handleAllDayToggle}
            onClick={(e) => e.stopPropagation()}
            aria-label="All-day"
            // data-[state=*] is the Radix switch, data-checked/data-unchecked
            // Base UI's. Notion's is 18x11 with a 9px white thumb
            className="data-[size=sm]:h-[11px] data-[size=sm]:w-[18px] **:data-[slot=switch-thumb]:!size-[9px] **:data-[slot=switch-thumb]:!bg-white data-[state=unchecked]:!bg-[#C7C5C1] data-unchecked:!bg-[#C7C5C1] dark:data-[state=unchecked]:!bg-[#595959] dark:data-unchecked:!bg-[#595959] data-[state=checked]:!bg-[#3A85D3] data-checked:!bg-[#3A85D3]"
          />
        }
      >
        <span className={EVENT_DETAIL_TEXT_CLASS}>All-day</span>
      </EventDetailRow>
    </EventDetailSection>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { selectInputSoon, useFieldPopover } from "@/hooks/use-field-popover";
import {
  EVENT_DETAIL_FIELD_BOX_CLASS,
  EventDetailFieldPopover,
} from "./event-detail-field-popover";
import {
  EVENT_DETAIL_GROUPED_INPUT_CLASS,
  EVENT_DETAIL_TEXT_CLASS,
} from "./event-detail-parts";
import type { EventDetailTimeFieldProps, TimeOption } from "./week-view-types";

/** The menu's options while it's closed: none are built */
const NO_OPTIONS: TimeOption[] = [];

/** Times of an all-day event: muted and inert (Notion: #B9B9B9 / #595959) */
const ALL_DAY_TIME_CLASS = "text-[#B9B9B9] dark:text-[#595959]";

/**
 * A time's text ("7:45 AM"): Notion Calendar sets a narrow no-break space
 * before AM/PM, about 1px narrower than the space our labels keep
 */
const TIME_TEXT_CLASS = "[word-spacing:-1px]";

/**
 * Scrolls a list so `row` shows, the nearest way, without scrolling the
 * page or the panel the way `scrollIntoView` would
 */
function scrollRowIntoList(list: HTMLElement, row: HTMLElement) {
  const top = row.offsetTop;
  const bottom = top + row.offsetHeight;
  if (top < list.scrollTop) {
    list.scrollTop = top;
    return;
  }
  if (bottom > list.scrollTop + list.clientHeight) {
    list.scrollTop = bottom - list.clientHeight;
  }
}

/** Index of the menu row an event happened in, or null outside the rows */
function rowIndexOf(target: EventTarget | null): number | null {
  if (!(target instanceof Element)) return null;
  const row = target.closest<HTMLElement>("[data-index]");
  if (!row) return null;
  return Number(row.dataset.index);
}

/**
 * Props for TimeOptionRow
 */
interface TimeOptionRowProps {
  option: TimeOption;
  index: number;
  id: string;
  /** Under the pointer, or chosen with the keyboard */
  highlighted: boolean;
}

/** One row of the time menu: only the rows whose highlight changes render again */
const TimeOptionRow = React.memo(function TimeOptionRow({
  option,
  index,
  id,
  highlighted,
}: TimeOptionRowProps) {
  return (
    <div
      id={id}
      role="option"
      aria-selected={highlighted}
      data-index={index}
      className={cn(
        "h-[30.5px] cursor-default truncate rounded-[6px] px-1.5 leading-[30.5px] select-none",
        highlighted && "bg-[#303030]",
      )}
    >
      <span className={TIME_TEXT_CLASS}>{option.label}</span>
      {option.hint && (
        <>
          {" "}
          <span className="text-white/40">{option.hint}</span>
        </>
      )}
    </div>
  );
});

/**
 * A time field with Notion Calendar's floating time menu: every 15 minutes,
 * opened beside the panel with the current time in view. Typing lists the
 * times the text can mean; the arrow keys move through the options. The
 * field shows the option under the pointer or the keyboard's, but only sets
 * one on Enter, on a click, or on blur after typing or the arrow keys (the
 * field keeps focus after Enter and a click). Escape puts the time back.
 */
export function EventDetailTimeField({
  value,
  getOptions,
  getMatches,
  onCommit,
  formatValue,
  label,
  testId,
  panelRef,
  leading,
  trailing,
  disabled = false,
  readOnly = false,
  fitText = false,
  className,
}: EventDetailTimeFieldProps) {
  const listId = React.useId();
  const optionIdPrefix = React.useId();
  const inputRef = React.useRef<HTMLInputElement>(null);
  /** Last pointer position over the menu */
  const pointerRef = React.useRef<{ x: number; y: number } | null>(null);

  const [open, setOpen] = React.useState(false);
  /** Typed text the menu lists matches for, or null for every option */
  const [query, setQuery] = React.useState<string | null>(null);
  /** The option typing or the arrow keys reached, or null for the current time's */
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);
  /** Whether typing or the arrow keys chose the active option, which blur then sets */
  const [chosen, setChosen] = React.useState(false);
  /** The option under the pointer, shown in the field but never set by blur */
  const [hoverIndex, setHoverIndex] = React.useState<number | null>(null);
  const [list, setList] = React.useState<HTMLDivElement | null>(null);

  const formatted = formatValue(value);
  const [text, setText] = React.useState(formatted);

  // Follow the event: a commit, a drag on the calendar, another field
  React.useEffect(() => {
    setText(formatted);
  }, [formatted]);

  const interactive = !disabled && !readOnly;
  const isOpen = open && interactive;
  // Built as the menu opens, not on every change of the event (a drag)
  const options = React.useMemo(
    () => (isOpen ? getOptions() : NO_OPTIONS),
    [isOpen, getOptions],
  );
  const shown = React.useMemo(
    () => (query === null ? options : getMatches(query)),
    [query, options, getMatches],
  );
  const active =
    activeIndex ??
    shown.findIndex((option) => option.date.getTime() === value.getTime());
  const highlighted = hoverIndex ?? active;
  const hovered = hoverIndex === null ? undefined : shown[hoverIndex];
  const fieldText = hovered ? hovered.label : text;

  // Keep the active option in view: the current time when the menu opens,
  // then wherever the arrow keys move (the pointer's is in view already)
  React.useLayoutEffect(() => {
    if (!isOpen || !list || active < 0) return;
    const row = list.querySelector<HTMLElement>(`[data-index="${active}"]`);
    if (row) scrollRowIntoList(list, row);
  }, [isOpen, list, active, shown]);

  const openMenu = () => {
    setQuery(null);
    setActiveIndex(null);
    setChosen(false);
    setHoverIndex(null);
    setOpen(true);
  };

  const closeMenu = () => {
    setOpen(false);
    setQuery(null);
    setActiveIndex(null);
    setChosen(false);
    setHoverIndex(null);
    pointerRef.current = null;
  };

  /** Sets an option, or puts the time back for none or one the event can't take */
  const setOption = (option: TimeOption | undefined) => {
    if (!option || option.date.getTime() === value.getTime()) {
      setText(formatted);
      return;
    }
    setText(onCommit(option.date) ? formatValue(option.date) : formatted);
  };

  const { inputProps, notePress, noteReturnFocus, escape } = useFieldPopover({
    inputRef,
    open: isOpen,
    onEnter: () => {
      openMenu();
      selectInputSoon(inputRef);
    },
    onCommit: () => {
      if (!chosen) {
        setText(formatted);
        return;
      }
      setOption(shown[active]);
    },
    onRestore: () => setText(formatted),
    onClose: closeMenu,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const typed = e.target.value;
    const isEmpty = typed.trim().length === 0;
    setText(typed);
    setQuery(isEmpty ? null : typed);
    setActiveIndex(isEmpty ? null : 0);
    setChosen(!isEmpty);
    setHoverIndex(null);
    setOpen(true);
  };

  /** Moves the keyboard's option from the highlighted one and shows it */
  const moveActive = (step: number) => {
    if (shown.length === 0) return;
    const from = highlighted >= 0 ? highlighted : step > 0 ? -1 : shown.length;
    const index = Math.min(Math.max(from + step, 0), shown.length - 1);
    setActiveIndex(index);
    setChosen(true);
    setHoverIndex(null);
    setText(shown[index].label);
    selectInputSoon(inputRef);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!open) {
        openMenu();
        return;
      }
      moveActive(e.key === "ArrowDown" ? 1 : -1);
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      setOption(shown[highlighted]);
      closeMenu();
      selectInputSoon(inputRef);
      return;
    }
    if (e.key !== "Escape") return;
    // With the menu closed (after Enter); before the calendar's global
    // Escape, which would deselect the event
    e.preventDefault();
    e.stopPropagation();
    escape();
  };

  /** A press on the focused field reopens a menu Enter closed */
  const handleClick = () => {
    if (!interactive || open) return;
    openMenu();
  };

  const handleListPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType === "touch") return;
    // The list scrolling under a still pointer isn't a hover
    const last = pointerRef.current;
    if (last && last.x === e.clientX && last.y === e.clientY) return;
    pointerRef.current = { x: e.clientX, y: e.clientY };
    const index = rowIndexOf(e.target);
    if (index === null || index === hoverIndex) return;
    setHoverIndex(index);
    selectInputSoon(inputRef);
  };

  const handleListPointerLeave = () => {
    pointerRef.current = null;
    if (hoverIndex === null) return;
    setHoverIndex(null);
    selectInputSoon(inputRef);
  };

  const handleListClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const index = rowIndexOf(e.target);
    if (index === null) return;
    setOption(shown[index]);
    closeMenu();
    selectInputSoon(inputRef);
  };

  const highlightedId =
    isOpen && shown[highlighted]
      ? `${optionIdPrefix}-${highlighted}`
      : undefined;

  const input = (
    <input
      ref={inputRef}
      data-testid={testId}
      type="text"
      role="combobox"
      aria-label={label}
      aria-expanded={isOpen}
      aria-controls={isOpen ? listId : undefined}
      aria-autocomplete="list"
      aria-activedescendant={highlightedId}
      autoComplete="off"
      spellCheck={false}
      value={fieldText}
      readOnly={!interactive}
      tabIndex={disabled ? -1 : undefined}
      onFocus={interactive ? inputProps.onFocus : undefined}
      onBlur={interactive ? inputProps.onBlur : undefined}
      onChange={handleChange}
      onKeyDown={interactive ? handleKeyDown : undefined}
      onClick={handleClick}
      // With `fitText`, the hidden copy of the text sizes the input instead
      size={fitText ? 1 : undefined}
      className={cn(
        "col-start-1 row-start-1 w-full min-w-0",
        TIME_TEXT_CLASS,
        EVENT_DETAIL_GROUPED_INPUT_CLASS,
        disabled
          ? cn(ALL_DAY_TIME_CLASS, "pointer-events-none")
          : EVENT_DETAIL_TEXT_CLASS,
        readOnly && "cursor-default",
      )}
    />
  );

  const field = (
    <>
      {leading}
      {fitText ? (
        <span className="flex min-w-0 items-center">
          {/* The hidden copy of the text sizes the input, so the duration follows it */}
          <span className="inline-grid min-w-0">
            <span
              aria-hidden
              className={cn(
                "invisible col-start-1 row-start-1 overflow-hidden whitespace-pre",
                TIME_TEXT_CLASS,
              )}
            >
              {fieldText || " "}
            </span>
            {input}
          </span>
          {trailing}
        </span>
      ) : (
        <>
          <span className="grid min-w-0 flex-1">{input}</span>
          {trailing}
        </>
      )}
    </>
  );

  return (
    <EventDetailFieldPopover
      open={isOpen}
      panelRef={panelRef}
      boxClassName={cn(
        EVENT_DETAIL_FIELD_BOX_CLASS,
        disabled && "pointer-events-none hover:border-transparent",
        readOnly && "cursor-default hover:border-transparent",
        className,
      )}
      onBoxClick={interactive ? () => inputRef.current?.focus() : undefined}
      onBoxPointerDown={notePress}
      field={field}
      inputRef={inputRef}
      onReturnFocus={noteReturnFocus}
      className="w-[219px]"
    >
      <div
        ref={setList}
        id={listId}
        role="listbox"
        aria-label={label}
        onPointerMove={handleListPointerMove}
        onPointerLeave={handleListPointerLeave}
        onClick={handleListClick}
        className="relative max-h-[236px] overflow-y-auto overscroll-contain p-1"
      >
        {shown.map((option, index) => (
          <TimeOptionRow
            key={option.date.getTime()}
            option={option}
            index={index}
            id={`${optionIdPrefix}-${index}`}
            highlighted={index === highlighted}
          />
        ))}
      </div>
    </EventDetailFieldPopover>
  );
}

"use client";

import * as React from "react";
import {
  addDays,
  addMonths,
  format,
  isBefore,
  isSameDay,
  startOfDay,
  startOfMonth,
} from "date-fns";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useDayPicker } from "react-day-picker";
import type { DayButtonProps, MonthCaptionProps } from "react-day-picker";

import { cn } from "@/lib/utils";
import { selectInputSoon, useFieldPopover } from "@/hooks/use-field-popover";
import { Calendar } from "@/components/ui/calendar";
import { useCalendarConfig } from "./calendar-provider";
import {
  EVENT_DETAIL_FIELD_BOX_CLASS,
  EventDetailFieldPopover,
} from "./event-detail-field-popover";
import {
  EVENT_DETAIL_GROUPED_INPUT_CLASS,
  EVENT_DETAIL_TEXT_CLASS,
} from "./event-detail-parts";
import { formatDateDisplay, parseDateInput } from "@/lib/time-input";
import type { EventDetailDateFieldProps } from "./week-view-types";

/** A day of the date picker: today, the event's day and hover fill a box */
const PICKER_DAY_CLASS =
  "relative isolate flex h-[30.5px] w-full items-center justify-center text-[13px] text-[#D4D4D4] outline-none before:absolute before:top-1/2 before:left-1/2 before:-z-10 before:h-[25px] before:w-[30px] before:-translate-1/2 before:rounded-[6px] hover:before:bg-[#303030]";

/** The date picker's previous and next month buttons */
const PICKER_CHEVRON_CLASS =
  "flex size-[24px] items-center justify-center justify-self-center rounded-[6px] text-[#848484] outline-none hover:bg-[#303030] disabled:opacity-40";

/**
 * Keys that move the marked day from the date field, the picker staying in
 * the field's hands: the arrows a day, Page Up and Page Down a month
 */
const DAY_STEPS: Partial<Record<string, (day: Date) => Date>> = {
  ArrowUp: (day) => addDays(day, -1),
  ArrowDown: (day) => addDays(day, 1),
  PageUp: (day) => addMonths(day, -1),
  PageDown: (day) => addMonths(day, 1),
};

/**
 * The date picker's header: "November 2026" with the previous and next
 * month chevrons over the last two columns
 */
function DatePickerCaption({ calendarMonth }: MonthCaptionProps) {
  const { locale } = useCalendarConfig();
  const { goToMonth, previousMonth, nextMonth } = useDayPicker();

  return (
    <div className="grid h-[33px] grid-cols-7 items-center">
      <span className="col-span-5 pl-[11px] text-[#D4D4D4]">
        {format(calendarMonth.date, "LLLL yyyy", { locale })}
      </span>
      <button
        type="button"
        aria-label="Previous month"
        disabled={!previousMonth}
        onClick={() => previousMonth && goToMonth(previousMonth)}
        className={PICKER_CHEVRON_CLASS}
      >
        <ChevronLeft className="size-4" />
      </button>
      <button
        type="button"
        aria-label="Next month"
        disabled={!nextMonth}
        onClick={() => nextMonth && goToMonth(nextMonth)}
        className={PICKER_CHEVRON_CLASS}
      >
        <ChevronRight className="size-4" />
      </button>
    </div>
  );
}

/**
 * A day of the date picker: today red, the event's day filled, days the
 * event can't take dimmed. Focus stays in the field, whose arrow keys move
 * the marked day.
 */
function DatePickerDayButton({
  // Kept off the button; DayPicker labels it
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  day,
  modifiers,
  className,
  ...props
}: DayButtonProps) {
  return (
    <button
      {...props}
      tabIndex={-1}
      className={cn(
        PICKER_DAY_CLASS,
        (modifiers.outside || modifiers.disabled) && "text-[#5F5F5F]",
        modifiers.disabled && "hover:before:bg-transparent",
        modifiers.selected && "before:bg-[#303030]",
        modifiers.today &&
          "text-white before:bg-[#F15550] hover:before:bg-[#F15550]",
        className,
      )}
    />
  );
}

/** Custom parts of the date picker, built once */
const DATE_PICKER_COMPONENTS = {
  MonthCaption: DatePickerCaption,
  DayButton: DatePickerDayButton,
};

/**
 * Class names of the date picker. They replace the shadcn/ui Calendar's own,
 * which differ between projects (and the repo's sidebar calendar)
 */
const DATE_PICKER_CLASS_NAMES = {
  root: "relative w-full",
  months: "flex flex-col",
  month: "flex flex-col",
  month_caption: "",
  caption_label: "",
  month_grid: "w-full border-collapse",
  weekdays: "flex",
  weekday:
    "flex h-[22px] flex-1 items-center justify-center text-[11px] font-medium text-[#898989] select-none",
  week: "flex",
  day: "flex-1 p-0",
  today: "",
  selected: "",
  outside: "",
  disabled: "",
  hidden: "invisible",
};

/**
 * A date field with Notion Calendar's date picker beside the panel. Typing
 * a date ("Nov 12") or the arrow keys mark a day in the picker; Enter or
 * blur sets it, as does a click on a day (which closes the picker and leaves
 * the field). Escape puts the date back. A day the event can't take (an end
 * before the start) puts the date back too.
 */
export function EventDetailDateField({
  value,
  onCommit,
  minDate,
  label,
  testId,
  panelRef,
  readOnly = false,
  className,
}: EventDetailDateFieldProps) {
  const { locale, weekStartsOn } = useCalendarConfig();
  const pickerId = React.useId();
  const inputRef = React.useRef<HTMLInputElement>(null);

  const formatted = formatDateDisplay(value, locale);
  const [text, setText] = React.useState(formatted);
  const [open, setOpen] = React.useState(false);
  /** The day typing or the arrow keys marked in the picker, before it's set */
  const [markedDay, setMarkedDay] = React.useState<Date | null>(null);
  const [month, setMonth] = React.useState(() => startOfMonth(value));

  React.useEffect(() => {
    setText(formatted);
  }, [formatted]);

  const isOpen = open && !readOnly;

  /** Sets a day, or puts the date back when it's the same or the event can't take it */
  const setDay = (day: Date) => {
    if (isSameDay(day, value) || !onCommit(day)) {
      setText(formatted);
      return;
    }
    setText(formatDateDisplay(day, locale));
  };

  /** Sets the marked or typed day, or puts the date back when the text isn't one */
  const commitMarked = () => {
    const day = markedDay ?? parseDateInput(text, value, locale);
    if (!day) {
      setText(formatted);
      return;
    }
    setDay(day);
  };

  const close = () => {
    setOpen(false);
    setMarkedDay(null);
  };

  const openPicker = () => {
    setMarkedDay(null);
    setMonth(startOfMonth(value));
    setOpen(true);
    selectInputSoon(inputRef);
  };

  const { inputProps, notePress, noteReturnFocus, escape, leave } =
    useFieldPopover({
      inputRef,
      open: isOpen,
      onEnter: openPicker,
      onCommit: commitMarked,
      onRestore: () => setText(formatted),
      onClose: close,
    });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setText(e.target.value);
    const day = parseDateInput(e.target.value, value, locale);
    setMarkedDay(day);
    if (day) setMonth(startOfMonth(day));
    setOpen(true);
  };

  /** Marks a day and shows it, unless it's before `minDate` */
  const markDay = (day: Date) => {
    if (minDate && isBefore(day, startOfDay(minDate))) return;
    setMarkedDay(day);
    setText(formatDateDisplay(day, locale));
    setMonth(startOfMonth(day));
    setOpen(true);
    selectInputSoon(inputRef);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const step = DAY_STEPS[e.key];
    if (step) {
      e.preventDefault();
      markDay(step(markedDay ?? value));
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      commitMarked();
      close();
      selectInputSoon(inputRef);
      return;
    }
    if (e.key !== "Escape") return;
    // With the picker closed (after Enter); before the calendar's global
    // Escape, which would deselect the event
    e.preventDefault();
    e.stopPropagation();
    escape();
  };

  const handleDayClick = (day: Date) => {
    setDay(day);
    leave();
  };

  const field = (
    <input
      ref={inputRef}
      data-testid={testId}
      type="text"
      role="combobox"
      aria-label={label}
      aria-haspopup="dialog"
      aria-expanded={isOpen}
      aria-controls={isOpen ? pickerId : undefined}
      autoComplete="off"
      spellCheck={false}
      value={text}
      readOnly={readOnly}
      onFocus={readOnly ? undefined : inputProps.onFocus}
      onBlur={readOnly ? undefined : inputProps.onBlur}
      onChange={handleChange}
      onKeyDown={readOnly ? undefined : handleKeyDown}
      onClick={() => !readOnly && !open && openPicker()}
      className={cn(
        "w-full min-w-0",
        EVENT_DETAIL_GROUPED_INPUT_CLASS,
        EVENT_DETAIL_TEXT_CLASS,
        readOnly && "cursor-default",
      )}
    />
  );

  return (
    <EventDetailFieldPopover
      open={isOpen}
      panelRef={panelRef}
      boxClassName={cn(
        EVENT_DETAIL_FIELD_BOX_CLASS,
        "pl-[8px]",
        readOnly && "cursor-default hover:border-transparent",
        className,
      )}
      onBoxClick={readOnly ? undefined : () => inputRef.current?.focus()}
      onBoxPointerDown={notePress}
      field={field}
      inputRef={inputRef}
      onReturnFocus={noteReturnFocus}
      className="w-[272px] p-2"
    >
      <Calendar
        id={pickerId}
        // With onSelect, DayPicker follows `selected` (the marked day) as it changes
        mode="single"
        required
        selected={markedDay ?? value}
        onSelect={handleDayClick}
        disabled={minDate ? { before: minDate } : undefined}
        month={month}
        onMonthChange={setMonth}
        showOutsideDays
        fixedWeeks
        hideNavigation
        locale={locale}
        // The calendar's first day; the locale's outside a provider
        weekStartsOn={weekStartsOn ?? locale.options?.weekStartsOn ?? 0}
        formatters={{
          formatWeekdayName: (date) => format(date, "EEEEEE", { locale }),
        }}
        components={DATE_PICKER_COMPONENTS}
        classNames={DATE_PICKER_CLASS_NAMES}
        className="bg-transparent p-0"
      />
    </EventDetailFieldPopover>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { FIELD_POPOVER_ATTRIBUTE } from "@/hooks/use-field-popover";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  EVENT_DETAIL_INPUT_GROUP_CLASS,
  EVENT_DETAIL_MENU_CLASS,
} from "./event-detail-parts";
import type { EventDetailFieldPopoverProps } from "./week-view-types";

/**
 * Gap between the panel's left edge and the time menu or date picker, which
 * open beside the panel, top-aligned with their field (Notion: 6px)
 */
const POPOVER_PANEL_GAP = 6;

/** Marks the popover for `useFieldPopover`, whose focus goes back to the field */
const FIELD_POPOVER_DATA = { [FIELD_POPOVER_ATTRIBUTE]: "" };

/**
 * The time menu and the date picker: dark in both themes like the panel's
 * other menus, and shown at once, without the enter or exit animation of
 * Radix (`data-state`) or Base UI (`data-open`, `data-closed`)
 */
const FIELD_POPOVER_CLASS = cn(
  EVENT_DETAIL_MENU_CLASS,
  "rounded-[10px] border p-0 text-sm font-medium text-white shadow-[0_8px_24px_rgb(0_0_0/0.24)] ring-0 outline-none",
  "data-[state=open]:animate-none data-[state=closed]:animate-none data-open:animate-none data-closed:animate-none",
);

/** A field's box: 31px tall in its 35px row, bordered on hover, filled on focus */
export const EVENT_DETAIL_FIELD_BOX_CLASS = cn(
  "relative flex h-[31px] min-w-0 items-center",
  EVENT_DETAIL_INPUT_GROUP_CLASS,
);

/**
 * Distance from a field's box to the panel's left edge plus the gap, the
 * side offset that opens its popover beside the panel
 */
function getPopoverOffset(
  box: HTMLElement | null,
  panel: HTMLElement | null,
): number {
  if (!box || !panel) return POPOVER_PANEL_GAP;
  return (
    box.getBoundingClientRect().left -
    panel.getBoundingClientRect().left +
    POPOVER_PANEL_GAP
  );
}

/**
 * A field's box, and its menu or picker in the shadcn/ui Popover, opened
 * left of the panel and top-aligned with the box, as in Notion Calendar.
 * The input keeps focus while it's open: the popover moves focus into itself
 * as it opens (Radix and Base UI both do), and hands it straight back, and
 * presses inside it never take focus. The trigger is a disabled, hidden
 * button over the box, there only to place the popover, so closing never
 * returns focus to it. The field opens and closes the popover itself, on
 * focus, blur, Enter and Escape (`useFieldPopover`).
 */
export function EventDetailFieldPopover({
  open,
  panelRef,
  boxClassName,
  onBoxClick,
  onBoxPointerDown,
  field,
  inputRef,
  onReturnFocus,
  className,
  children,
}: EventDetailFieldPopoverProps) {
  const boxRef = React.useRef<HTMLDivElement>(null);
  const [sideOffset, setSideOffset] = React.useState(POPOVER_PANEL_GAP);

  // Measured as it opens, before it's painted
  React.useLayoutEffect(() => {
    if (!open) return;
    setSideOffset(getPopoverOffset(boxRef.current, panelRef.current));
  }, [open, panelRef]);

  const handleFocusCapture = () => {
    const input = inputRef.current;
    if (!input || document.activeElement === input) return;
    onReturnFocus();
    input.focus({ preventScroll: true });
  };

  return (
    <Popover open={open}>
      <div
        ref={boxRef}
        className={boxClassName}
        onClick={onBoxClick}
        onPointerDown={onBoxPointerDown}
      >
        <PopoverTrigger asChild disabled>
          <button
            type="button"
            tabIndex={-1}
            aria-hidden
            className="pointer-events-none absolute -inset-px opacity-0"
          />
        </PopoverTrigger>
        {field}
      </div>
      <PopoverContent
        side="left"
        align="start"
        sideOffset={sideOffset}
        {...FIELD_POPOVER_DATA}
        onFocusCapture={handleFocusCapture}
        onMouseDown={(e) => e.preventDefault()}
        className={cn(FIELD_POPOVER_CLASS, className)}
      >
        {children}
      </PopoverContent>
    </Popover>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  autoUpdate,
  flip,
  offset,
  shift,
  size,
  useFloating,
} from "@floating-ui/react-dom";
import { Globe, History } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import {
  EVENT_DETAIL_HOVER_BORDER_CLASS,
  EVENT_DETAIL_ICON_CLASS,
  EVENT_DETAIL_MENU_CLASS,
  EVENT_DETAIL_ROW_HEIGHT_CLASS,
  EVENT_DETAIL_SECONDARY_CLASS,
  EventDetailRow,
  EventDetailSection,
  getEventDetailPortalContainer,
} from "./event-detail-parts";
import {
  POPULAR_TIME_ZONES,
  changeTimeZoneKeepingWallClock,
  getEventTimeZone,
  getTimeZoneOption,
  getTimeZoneOptions,
  getTimeZoneRowLabel,
  getViewerTimeZone,
  searchTimeZones,
  splitSearchMatch,
} from "@/lib/time-zones";
import type {
  DetailedCalendarEvent,
  EventDetailSectionProps,
  TimeZoneOption,
} from "./week-view-types";

/** How many picked zones the picker remembers at its top */
const MAX_RECENT_TIME_ZONES = 5;

/**
 * Gap between the row's hover box and the zone list beside the details, in
 * px: the list ends 7px left of the panel, as in Notion Calendar
 */
const LIST_OFFSET = 12;

/** Keeps the zone list this far from the viewport's edges, in px */
const LIST_VIEWPORT_PADDING = 8;

/** Tallest the zone list grows, in px (Notion Calendar: 345) */
const LIST_MAX_HEIGHT = 345;

/**
 * The row's 31px box, which draws the hover border and the editing fill: it
 * starts 5px from the panel's edge, so the icon stays on the panel's 26px
 * icon column, and ends 10px before the other edge
 */
const ROW_BOX_CLASS =
  "-mr-1.5 -ml-[13px] flex h-[31px] min-w-0 flex-1 items-center gap-[11px] rounded-sm pr-2 pl-3";

/** Zone text in the list, which is dark in both themes */
const LIST_TEXT_CLASS = "text-[#D4D4D4]";

/** Offsets and unmatched text in the list */
const LIST_MUTED_TEXT_CLASS = "text-[#7F7F7F]";

/** The row while it holds the search input: filled like a focused input */
const EDITING_ROW_CLASS =
  "border-[#F5F5F5] bg-[#F5F5F5] dark:border-[#242424] dark:bg-[#242424]";

/** Rendered on the server and during hydration, where the viewer's zone is unknown */
const SERVER_TIME_ZONE = "";

/**
 * A group of the zone list
 */
interface TimeZoneSection {
  /** Prefixes each item's value, so a zone listed twice stays two items */
  key: "recent" | "popular" | "all" | "search";
  options: TimeZoneOption[];
}

/** Zones picked during this page's life, most recent first */
let recentTimeZones: string[] = [];

/** Pickers showing the recent zones, told when they change */
const recentTimeZoneListeners = new Set<() => void>();

function subscribeToRecentTimeZones(listener: () => void): () => void {
  recentTimeZoneListeners.add(listener);
  return () => recentTimeZoneListeners.delete(listener);
}

function getRecentTimeZones(): string[] {
  return recentTimeZones;
}

/** Puts `timeZone` first among the recent zones */
function rememberTimeZone(timeZone: string): void {
  recentTimeZones = [
    timeZone,
    ...recentTimeZones.filter((zone) => zone !== timeZone),
  ].slice(0, MAX_RECENT_TIME_ZONES);
  for (const listener of recentTimeZoneListeners) listener();
}

/** No-op subscription: the viewer's zone doesn't change while the page is open */
function subscribeToViewerTimeZone(): () => void {
  return () => {};
}

function getServerTimeZone(): string {
  return SERVER_TIME_ZONE;
}

/** Value of a zone's list item, e.g. "recent:America/Sao_Paulo" */
function getItemValue(section: TimeZoneSection["key"], timeZone: string) {
  return `${section}:${timeZone}`;
}

/** The zone of a list item's value */
function getItemTimeZone(value: string): string {
  return value.slice(value.indexOf(":") + 1);
}

/**
 * Index of the item an arrow key moves the highlight to: one step from
 * `index`, kept inside the list; the first or last item when nothing is
 * highlighted
 */
function getSteppedIndex(index: number, step: 1 | -1, count: number): number {
  if (index === -1) return step === 1 ? 0 : count - 1;
  return Math.min(Math.max(index + step, 0), count - 1);
}

/**
 * "Brasilia Standard Time – Sao Paulo", with the part matching the search in
 * bold white and the rest dimmed while searching
 */
function ZoneText({ text, query }: { text: string; query: string | null }) {
  if (query === null) return <>{text}</>;

  const { before, match, after } = splitSearchMatch(text, query);
  return (
    <span className={LIST_MUTED_TEXT_CLASS}>
      {before}
      {match && <span className="font-semibold text-white">{match}</span>}
      {after}
    </span>
  );
}

/**
 * The event's time zone, "GMT−3 Sao Paulo". Clicking it turns the row into a
 * search field with the zone list beside the details: recent zones, popular
 * ones, then every zone by offset. Arrow keys and the pointer move through
 * the list and preview the city in the field, typing filters it by name or
 * city, Enter or a click picks a zone, Escape restores the zone from before
 * the list opened (the highlight only previews). Picking a
 * zone keeps the event's wall-clock times, so 8 AM in São Paulo becomes 8 AM
 * in New York. All-day events have no zone.
 */
export function EventDetailTimezone<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
>({ event, onEventChange }: EventDetailSectionProps<TEvent>) {
  const listId = React.useId();
  const inputRef = React.useRef<HTMLInputElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  /** Scrolls the highlighted item into view once the list has rendered it */
  const scrollToActiveRef = React.useRef(false);

  const [editing, setEditing] = React.useState(false);
  const [listOpen, setListOpen] = React.useState(false);
  /** The typed search, or null while the field shows a city */
  const [query, setQuery] = React.useState<string | null>(null);
  const [activeValue, setActiveValue] = React.useState("");
  const [inputText, setInputText] = React.useState("");
  const [rowElement, setRowElement] = React.useState<HTMLElement | null>(null);
  /** Id of the highlighted option, for the field's `aria-activedescendant` */
  const [activeOptionId, setActiveOptionId] = React.useState<string>();
  const [listElement, setListElement] = React.useState<HTMLElement | null>(
    null,
  );

  const viewerTimeZone = React.useSyncExternalStore(
    subscribeToViewerTimeZone,
    getViewerTimeZone,
    getServerTimeZone,
  );
  const recent = React.useSyncExternalStore(
    subscribeToRecentTimeZones,
    getRecentTimeZones,
    getRecentTimeZones,
  );

  const { floatingStyles, isPositioned } = useFloating({
    open: listOpen,
    placement: "left-start",
    strategy: "fixed",
    elements: { reference: rowElement, floating: listElement },
    whileElementsMounted: autoUpdate,
    middleware: [
      offset(LIST_OFFSET),
      flip({ fallbackPlacements: ["bottom-start", "right-start"] }),
      shift({ padding: LIST_VIEWPORT_PADDING }),
      size({
        padding: LIST_VIEWPORT_PADDING,
        apply({ availableHeight, elements }) {
          elements.floating.style.maxHeight = `${Math.min(availableHeight, LIST_MAX_HEIGHT)}px`;
        },
      }),
    ],
  });

  const eventTimeZone = React.useMemo(
    () =>
      getEventTimeZone({ timeZone: event.timeZone, timezone: event.timezone }),
    [event.timeZone, event.timezone],
  );
  const timeZone = eventTimeZone ?? viewerTimeZone;

  // Every zone, listed once per edit: typing searches this list
  const startTime = event.start.getTime();
  const options = React.useMemo(
    () => (editing ? getTimeZoneOptions(new Date(startTime)) : []),
    [editing, startTime],
  );

  const sections = React.useMemo<TimeZoneSection[]>(() => {
    if (!listOpen) return [];
    if (query !== null) {
      return [{ key: "search", options: searchTimeZones(options, query) }];
    }
    const byId = new Map(options.map((option) => [option.id, option]));
    const pick = (ids: string[]) =>
      ids.flatMap((id) => {
        const option = byId.get(id) ?? getTimeZoneOption(event.start, id);
        return option ? [option] : [];
      });
    const groups: TimeZoneSection[] = [
      { key: "recent", options: pick(recent) },
      { key: "popular", options: pick(POPULAR_TIME_ZONES) },
      { key: "all", options },
    ];
    return groups.filter((group) => group.options.length > 0);
  }, [listOpen, query, options, recent, event.start]);

  const itemValues = React.useMemo(
    () =>
      sections.flatMap((section) =>
        section.options.map((option) => getItemValue(section.key, option.id)),
      ),
    [sections],
  );

  const cityOf = React.useCallback(
    (zone: string) => getTimeZoneRowLabel(event.start, zone).city,
    [event.start],
  );

  // Keep the highlighted item in view after the keyboard moved it or the
  // list opened on it, once the list is placed and its height capped
  React.useEffect(() => {
    if (!isPositioned || !scrollToActiveRef.current || !listRef.current) {
      return;
    }
    scrollToActiveRef.current = false;
    const item = Array.from(
      listRef.current.querySelectorAll<HTMLElement>("[cmdk-item]"),
    ).find((element) => element.dataset.value === activeValue);
    item?.scrollIntoView({ block: "nearest" });
  }, [activeValue, sections, isPositioned]);

  // cmdk ids its options itself: read the highlighted one's from the list
  React.useEffect(() => {
    const item = listOpen
      ? Array.from(
          listRef.current?.querySelectorAll<HTMLElement>("[cmdk-item]") ?? [],
        ).find((element) => element.dataset.value === activeValue)
      : undefined;
    setActiveOptionId(item?.id || undefined);
  }, [activeValue, sections, listOpen, listElement]);

  // Select the city once the field has rendered it
  React.useEffect(() => {
    if (!editing || query !== null) return;
    inputRef.current?.select();
  }, [editing, query, inputText]);

  const close = () => {
    setEditing(false);
    setListOpen(false);
    setQuery(null);
  };

  const open = () => {
    if (!onEventChange || !timeZone) return;
    setEditing(true);
    setListOpen(true);
    setQuery(null);
    setInputText(cityOf(timeZone));
    setActiveValue(
      getItemValue(recent.includes(timeZone) ? "recent" : "all", timeZone),
    );
    scrollToActiveRef.current = true;
    requestAnimationFrame(() => {
      inputRef.current?.focus();
      inputRef.current?.select();
    });
  };

  const pick = (zone: string) => {
    rememberTimeZone(zone);
    setListOpen(false);
    setQuery(null);
    setInputText(cityOf(zone));
    if (zone === timeZone) return;
    onEventChange?.({
      ...event,
      timeZone: zone,
      start: changeTimeZoneKeepingWallClock(event.start, timeZone, zone),
      end: changeTimeZoneKeepingWallClock(event.end, timeZone, zone),
    });
  };

  /** Highlights a list item; outside a search the field previews its city */
  const highlight = (value: string) => {
    setActiveValue(value);
    if (query === null) setInputText(cityOf(getItemTimeZone(value)));
  };

  const moveHighlight = (step: 1 | -1) => {
    if (itemValues.length === 0) return;
    const index = itemValues.indexOf(activeValue);
    scrollToActiveRef.current = true;
    highlight(itemValues[getSteppedIndex(index, step, itemValues.length)]);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!listOpen) {
        open();
        return;
      }
      moveHighlight(e.key === "ArrowDown" ? 1 : -1);
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      if (listOpen && activeValue) {
        pick(getItemTimeZone(activeValue));
        return;
      }
      inputRef.current?.blur();
      return;
    }
    if (e.key === "Escape") {
      // Keep the calendar's global Escape from deselecting the event
      e.stopPropagation();
      e.preventDefault();
      inputRef.current?.blur();
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value;
    setInputText(text);
    // An emptied field lists the sections again
    setQuery(text.trim() ? text : null);
    setListOpen(true);
    const results = searchTimeZones(options, text);
    setActiveValue(results[0] ? getItemValue("search", results[0].id) : "");
    scrollToActiveRef.current = true;
  };

  if (event.isAllDay) return null;

  // Before hydration the viewer's zone is unknown: show the legacy label
  if (!timeZone) {
    return (
      <EventDetailSection name="timezone">
        <EventDetailRow icon={Globe}>
          <span className={EVENT_DETAIL_SECONDARY_CLASS}>{event.timezone}</span>
        </EventDetailRow>
      </EventDetailSection>
    );
  }

  const label = getTimeZoneRowLabel(event.start, timeZone);
  // Inside a modal sheet (the panel on phones), which dismisses on presses
  // outside its own DOM; the body anywhere else
  const portalContainer = listOpen
    ? getEventDetailPortalContainer(rowElement)
    : null;

  return (
    <EventDetailSection name="timezone">
      <div
        className={cn(
          "flex items-center pr-4 pl-[18px]",
          EVENT_DETAIL_ROW_HEIGHT_CLASS,
        )}
      >
        {editing ? (
          <div
            ref={setRowElement}
            className={cn(
              ROW_BOX_CLASS,
              "cursor-text border",
              EDITING_ROW_CLASS,
            )}
            onClick={() => inputRef.current?.focus()}
          >
            <Globe className={EVENT_DETAIL_ICON_CLASS} />
            <input
              ref={inputRef}
              type="text"
              role="combobox"
              aria-label="Time zone"
              aria-expanded={listOpen}
              aria-controls={listOpen ? listId : undefined}
              aria-activedescendant={activeOptionId}
              aria-autocomplete="list"
              value={inputText}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
              onBlur={close}
              className="min-w-0 flex-1 border-none bg-transparent p-0 outline-none"
            />
          </div>
        ) : (
          <button
            ref={setRowElement}
            type="button"
            aria-label={`Time zone: ${label.offset} ${label.city}`}
            disabled={!onEventChange}
            onClick={open}
            className={cn(
              EVENT_DETAIL_HOVER_BORDER_CLASS,
              ROW_BOX_CLASS,
              "text-left outline-none disabled:cursor-default disabled:hover:border-transparent",
              "focus-visible:border-[#3A85D3] dark:focus-visible:border-[#3A85D3]",
            )}
          >
            <Globe className={EVENT_DETAIL_ICON_CLASS} />
            <span className="flex min-w-0 items-center gap-[5px]">
              <span className={cn("shrink-0", EVENT_DETAIL_SECONDARY_CLASS)}>
                {label.offset}
              </span>
              <span className="truncate">{label.city}</span>
            </span>
          </button>
        )}
      </div>

      {listOpen &&
        portalContainer &&
        createPortal(
          <div
            ref={setListElement}
            id={listId}
            style={floatingStyles}
            className={cn(
              "pointer-events-auto z-50 flex w-[413px] max-w-[calc(100vw-16px)] flex-col overflow-hidden rounded-lg border font-medium shadow-lg",
              EVENT_DETAIL_MENU_CLASS,
            )}
            // The field keeps focus while the pointer uses the list
            onMouseDown={(e) => e.preventDefault()}
          >
            <Command
              shouldFilter={false}
              value={activeValue}
              onValueChange={highlight}
              className="min-h-0 flex-1 rounded-none bg-transparent text-sm"
            >
              <CommandList
                ref={listRef}
                // cmdk names the listbox from `label`, and ids it itself
                label="Time zones"
                className="max-h-none min-h-0 flex-1 overflow-y-auto"
              >
                {/* Keeps the list, and so Escape's restore, while nothing matches */}
                <CommandEmpty
                  className={cn(
                    "px-2.5 py-[7px] text-sm",
                    LIST_MUTED_TEXT_CLASS,
                  )}
                >
                  No results
                </CommandEmpty>
                {sections.map((section, index) => (
                  <React.Fragment key={section.key}>
                    {index > 0 && (
                      <CommandSeparator className="mx-0 bg-[#303030]" />
                    )}
                    <CommandGroup className="p-1">
                      {section.options.map((option) => (
                        <CommandItem
                          key={option.id}
                          value={getItemValue(section.key, option.id)}
                          onSelect={() => pick(option.id)}
                          className={cn(
                            "h-[30px] gap-[9px] rounded-md py-0 pr-2 pl-1.5 text-sm data-[selected=true]:bg-[#303030]",
                            LIST_TEXT_CLASS,
                            "data-[selected=true]:text-[#D4D4D4]",
                          )}
                        >
                          <span
                            className={cn("shrink-0", LIST_MUTED_TEXT_CLASS)}
                          >
                            {option.offsetLabel}
                          </span>
                          <span className="min-w-0 flex-1 truncate">
                            <ZoneText text={option.name} query={query} />
                            <span
                              className={cn(
                                "whitespace-pre",
                                query !== null && LIST_MUTED_TEXT_CLASS,
                              )}
                            >
                              {"  –  "}
                            </span>
                            <ZoneText text={option.city} query={query} />
                          </span>
                          {section.key === "recent" && (
                            <History
                              aria-label="Recent"
                              className={cn(
                                "size-3.5 shrink-0",
                                LIST_MUTED_TEXT_CLASS,
                              )}
                            />
                          )}
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  </React.Fragment>
                ))}
              </CommandList>
            </Command>
          </div>,
          portalContainer,
        )}
    </EventDetailSection>
  );
}

